+}
+
+/// Take the content between the first `(` and its matching `)`.
+fn paren_inner(s: &str) -> String {
+    let s = s.trim_start();
+    let Some(start) = s.find('(') else {
+        return String::new();
+    };
+    let bytes = s.as_bytes();
+    let mut depth = 0i32;
+    let mut in_str = false;
+    let mut i = start;
+    while i < bytes.len() {
+        let c = bytes[i];
+        if in_str {
+            if c == b'\\' {
+                i += 2;
+                continue;
+            }
+            if c == b'"' {
+                in_str = false;
+            }
+            i += 1;
+            continue;
+        }
+        match c {
+            b'"' => in_str = true,
+            b'(' => depth += 1,
+            b')' => {
+                depth -= 1;
+                if depth == 0 {
+                    return s[start + 1..i].to_string();
+                }
+            }
+            _ => {}
+        }
+        i += 1;
+    }
+    s[start + 1..].to_string()
+}
